<template>
  <div class="employee-card">
    <v-icon size="55" class="mx-2">mdi-account-circle</v-icon>
    <div class="d-flex flex-column">
      <FormattedText type="text-h6" :value="employee.name" />
      <FormattedText type="text-caption" class="text-left">
        <v-icon size="7" v-for="i in 10" :key="i">mdi-asterisk</v-icon>
      </FormattedText>
    </div>
    <div>
      <ChipList
        :list="permissions"
        :listEnabled="employee"
        disabled
        class="employee-permissions__chips"
      />
    </div>
  </div>
</template>

<script>
import employeePermissions from '@/config/employeePermissions'

import FormattedText from '@/components/shared/FormattedText'
import ChipList from '@/components/shared/ChipList'

export default {
  name: 'EmployeeInfo',
  components: { ChipList, FormattedText },
  props: {
    employee: {
      type: Object,
      required: true,
    },
  },
  computed: {
    permissions() {
      return employeePermissions
    },
  },
}
</script>

<style lang="scss" scoped>
.employee-card {
  display: grid;
  grid-template-columns: min-content 1fr 3fr min-content;
  align-items: center;
  .flex-column {
    width: 225px;
  }
  .employee-permissions__chips {
    gap: 10px;
    :deep(.accent.v-chip--disabled) {
      opacity: 1;
    }
  }
}
</style>
