<template>
  <div class="pb-6 mt-4">
    <FormattedText
      type="text-subtitle-1"
      color="textPrimary"
      intl
      value="preferences.app.defaultProductsFilter"
      class="text-left mb-2"
      className="font-weight-bold"
    />
    <v-select
      v-model="selected"
      :items="items"
      filled
      rounded
      class="filter-select custom-text-field"
      @change="changeFilterSelected"
    />
  </div>
</template>

<script>
import { mapState, mapActions } from 'vuex'

import { getTranslatedText } from '@/tools/data'

import appActions from '@/store/app/actions.types'

import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'AppDefaultProductsFilterPreference',
  components: { FormattedText },
  data() {
    return {
      selected: 'all',
      items: [
        {
          text: this.getTranslatedText('preferences.app.allFilterOption'),
          value: 'all',
        },
        {
          text: this.getTranslatedText('preferences.app.byWeightFilterOption'),
          value: 'byWeight',
        },
        {
          text: this.getTranslatedText('preferences.app.favoritesFilterOption'),
          value: 'favorites',
        },
      ],
    }
  },
  computed: {
    ...mapState('app', ['defaultProductsFilter']),
  },
  methods: {
    getTranslatedText,
    ...mapActions('app', [appActions.setDefaultProductsFilter]),
    changeFilterSelected() {
      this.$track({
        type: 'interaction',
        action: 'change',
        category: 'Preferences',
        screen: 'App',
        name: 'Change default filter on products',
      })
      this[appActions.setDefaultProductsFilter](this.selected)
    },
  },
  mounted() {
    this.selected = this.defaultProductsFilter
  },
}
</script>

<style lang="scss" scoped>
.filter-select {
  width: 225px;
}
</style>
