<template>
  <DialogCard :config="config.dialogData"> </DialogCard>
</template>

<script>
import { mapActions, mapState } from 'vuex'

import appActions from '@/store/app/actions.types'

import DialogCard from '@/components/shared/DialogCard'
import setConfig from '@/components/PreferencesView/AdminPreferences/RestoreStockProducts/RestoreStockConfirmationDialog/config'

export default {
  name: 'RestoreStockConfirmationDialog',
  components: { DialogCard },
  props: {
    restoreNegativeStock: {
      type: Boolean,
      default: false,
    },
  },
  computed: {
    ...mapState('app', ['restoreStockConfirmationDialog']),
    config() {
      return setConfig(
        {
          isOpen: this.restoreStockConfirmationDialog.isOpen,
          restoreNegativeStock: this.restoreNegativeStock,
        },
        {
          closeDialog: this.closeDialog,
          acceptRestore: this.acceptRestore,
        }
      )
    },
  },
  methods: {
    ...mapActions('app', [appActions.setRestoreStockConfirmationDialogStatus]),
    closeDialog() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Preferences',
        screen: 'RestoreStockConfirmationDialog',
        name: 'Cancel',
      })
      this[appActions.setRestoreStockConfirmationDialogStatus]({
        isOpen: false,
      })
    },
    acceptRestore() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Preferences',
        screen: 'RestoreStockConfirmationDialog',
        name: 'Submit',
      })
      this.$emit('acceptRestore')
    },
  },
}
</script>
