import { required, decimal } from 'vuelidate/lib/validators'

const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.opened,
    icon: 'mdi-credit-card-wireless',
    title: 'airtimeView.loadBalanceDialog.title',
    titleBackground: '#white',
    titleColor: 'textPrimary',
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    height: 550,
    maxWidth: 500,
    isAcceptButtonDisabled: state.isAcceptButtonDisabled,
    id: 'add-airtime-services-balance-form',
    onClickCancel: () => {
      methods.track({
        type: 'interaction',
        action: 'click',
        category: 'Preferences',
        screen: 'AddAirtimeServicesBalance',
        name: 'Cancel',
      })
      methods.closeDialog()
    },
    onClickAccept: () => methods.loadBalance(),
  },
  fields: [
    {
      id: 'bank',
      type: 'select',
      label: 'airtimeView.loadBalanceDialog.bankSelect',
      items: state.bankItems,
      itemValue: 'value',
      errorMessage: 'airtimeView.loadBalanceDialog.errorMessage.bankSelect',
      color: 'primaryColor',
      required: true,
      validators: { required },
    },
    {
      id: 'depositDate',
      type: 'input',
      valueType: 'date',
      label: 'airtimeView.loadBalanceDialog.depositDate',
      errorMessage: 'airtimeView.loadBalanceDialog.errorMessage.depositDate',
      color: 'primaryColor',
      required: true,
      validators: { required },
    },
    {
      id: 'depositTime',
      type: 'input',
      valueType: 'time',
      step: 60,
      label: 'airtimeView.loadBalanceDialog.depositTime',
      errorMessage: 'airtimeView.loadBalanceDialog.errorMessage.depositTime',
      color: 'primaryColor',
      required: true,
      validators: { required },
    },
    {
      id: 'amount',
      type: 'input',
      valueType: 'number',
      label: 'shared.amount',
      errorMessage: 'airtimeView.loadBalanceDialog.errorMessage.amount',
      color: 'primaryColor',
      required: true,
      autofocus: true,
      validators: { required, decimal },
    },
    {
      id: 'authNumber',
      type: 'input',
      valueType: 'number',
      step: 1,
      label: 'airtimeView.loadBalanceDialog.authNumber',
      errorMessage: 'airtimeView.loadBalanceDialog.errorMessage.authNumber',
      color: 'primaryColor',
      required: true,
      validators: { required },
    },
  ],
  id: 'add-airtime-services-balance-form',
})

export default setConfig
