<template>
  <v-form class="text-left">
    <FormattedText
      type="text-subtitle-1"
      intl
      value="preferences.app.favoriteSections"
      className="font-weight-bold"
    />
    <v-chip
      v-for="item in menuItems"
      :key="item.id"
      class="mr-4 my-2"
      color="accent"
      :outlined="!mainMenuItems.includes(item.name)"
      @click="addOrRemoveSection(item.name)"
    >
      <v-avatar left>
        <v-icon :color="!mainMenuItems.includes(item.name) ? '' : 'white'">{{
          item.icon
        }}</v-icon>
      </v-avatar>
      <FormattedText
        :value="`mainLayout.navigation['${item.name}']`"
        intl
        :color="!mainMenuItems.includes(item.name) ? '' : 'white'"
        type="text-body-2"
        class="px-2"
      />
    </v-chip>
  </v-form>
</template>

<script>
import { mapState, mapActions } from 'vuex'
import { isNil } from 'ramda'

import appActions from '@/store/app/actions.types'

import menuConfig from '@/components/MainView/menuConfig'
import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'AppFavoritesPreference',
  components: {
    FormattedText,
  },
  data() {
    return {
      menuConfig: menuConfig,
    }
  },
  computed: {
    ...mapState('app', ['mainMenuItems']),
    menuItems() {
      return this.getVisibleMenuItems(this.menuConfig)
    },
  },
  methods: {
    ...mapActions('app', [appActions.addOrRemoveFavoritesSection]),
    getVisibleMenuItems: function(menu) {
      if (isNil(menu)) return []
      let toShow = []
      menu.forEach(item => {
        if (item.show) {
          if (item.path) toShow.push(item)
          else if (item.children) {
            item.children.forEach(child => {
              if (child.show) toShow.push(child)
            })
          }
        }
      })
      return toShow
    },
    addOrRemoveSection(item) {
      this.$track({
        type: 'interaction',
        action: 'change',
        category: 'Preferences',
        screen: 'App',
        name: 'Change favorite sections',
      })
      return this[appActions.addOrRemoveFavoritesSection](item)
    },
  },
}
</script>
