<template>
  <v-form>
    <FormattedText
      type="text-subtitle-1"
      color="textPrimary"
      intl
      value="preferences.app.language"
      class="text-left mb-2"
      className="font-weight-bold"
    />
    <v-select
      v-model="selectedLang"
      :key="selectedLang.localeIsoCode"
      :items="languages"
      item-text="name"
      item-value="localeIsoCode"
      required
      filled
      rounded
      class="lang-select custom-text-field"
      @change="changeSelectedLanguage"
    >
      <template v-slot:selection="{ item, index }">
        <div v-if="index === 0" color="chipPrimary">
          <span>{{ item.name }}</span>
        </div>
      </template>
      <template v-slot:append>
        <Flag :country="selectedLang.flag" size="small" />
      </template>
    </v-select>
  </v-form>
</template>

<script>
import languages from '@/config/languages'

import i18n from '@/plugins/i18n'

import FormattedText from '@/components/shared/FormattedText'
import Flag from '@/components/shared/Flag'

export default {
  name: 'AppLanguagePreference',
  components: {
    FormattedText,
    Flag,
  },
  data() {
    return {
      languages: languages,
      selectedLang: null,
    }
  },
  methods: {
    getLanguage(language) {
      return languages.find(lang => lang.localeIsoCode === language)
    },
    changeSelectedLanguage() {
      this.$track({
        type: 'interaction',
        action: 'change',
        category: 'Preferences',
        screen: 'App',
        name: 'Change language',
      })
      this.selectedLang = this.getLanguage(this.selectedLang)
      i18n.locale = this.selectedLang.localeIsoCode
    },
  },
  created() {
    this.selectedLang = this.getLanguage(i18n.locale)
  },
}
</script>

<style scoped>
.lang-select {
  width: 225px;
}
:deep(.v-select__selection--comma) {
  color: rgba(0, 0, 0, 0.54) !important;
}
:deep(.theme--light.v-list-item:not(.v-list-item--active):not(.v-list-item--disabled)) {
  color: rgba(0, 0, 0, 0.54) !important;
}
</style>
