<template>
  <div>
    <ActionsCard
      title="preferences.admin.changeAdminPassword"
      icon="mdi-lock"
      :actions="actions"
    />
    <ChangePasswordDialog v-if="changePasswordDialog.isOpen" />
  </div>
</template>

<script>
import { mapState, mapActions } from 'vuex'

import { getPhoneAccount } from '@/tools/data'

import appActions from '@/store/app/actions.types'

import ChangePasswordDialog from '@/components/ChangePasswordDialog'
import ActionsCard from '@/components/shared/ActionsCard'

export default {
  name: 'ChangePassword',
  components: { ActionsCard, ChangePasswordDialog },
  data() {
    return {
      actions: [
        {
          text: 'preferences.admin.changePassword',
          event: this.openChangePasswordDialog,
        },
      ],
    }
  },
  computed: {
    ...mapState('account', ['data']),
    ...mapState('app', ['changePasswordDialog']),
  },
  methods: {
    ...mapActions('app', [appActions.setChangePasswordDialogStatus]),
    openChangePasswordDialog() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Preferences',
        screen: 'Admin',
        name: 'Change password',
      })
      this[appActions.setChangePasswordDialogStatus]({
        isOpen: true,
        account: this.data.account.includes('@')
          ? this.data.account
          : getPhoneAccount(this.data.country.phoneCode, this.data.account),
      })
    },
  },
}
</script>

<style scoped lang="scss">
div {
  height: 100%;
}
</style>
