<template>
  <div>
    <ActionsCard title="preferences.admin.employees" icon="mdi-account-group">
      <div v-for="(employee, index) in employees" :key="employee._id">
        <v-card
          flat
          class="transparent d-flex justify-space-between pl-2 pt-2 pb-3 pr-5 my-2"
        >
          <EmployeeInfo :employee="employee" />
          <v-btn
            :ref="`editEmployee-${employee._id}`"
            color="primary"
            icon
            @click="enableFormEmployee(employee)"
            v-track:click="{
              category: 'Preferences',
              screen: 'Admin',
              name: 'Edit employee',
            }"
          >
            <v-icon>mdi-pencil</v-icon>
          </v-btn>
          <v-btn
            :ref="`deleteEmployee-${employee._id}`"
            :disabled="selectedUser.id === employee._id"
            color="primary"
            icon
            @click="switchConfirmationDeletionStatus(true, employee)"
            v-track:click="{
              category: 'Preferences',
              screen: 'Admin',
              name: 'Delete employee',
            }"
          >
            <v-icon>mdi-delete</v-icon>
          </v-btn>
        </v-card>
        <v-divider v-if="index < employees.length - 1" />
      </div>
      <div class="my-4 d-flex justify-end">
        <Button
          ref="addEmployeeButton"
          text="preferences.admin.addEmployee"
          intl
          @click="enableFormEmployee()"
          v-track:click="{
            category: 'Preferences',
            screen: 'Admin',
            name: 'Create employee',
          }"
        />
      </div>
    </ActionsCard>
    <DialogCard :config="config.dialogData" />
    <EmployeeForm
      v-if="employeeFormDialog.isOpen"
      :employeeToEdit="employeeToEdit"
      @saveEmployee="saveEmployee"
    />
  </div>
</template>

<script>
import { mapState, mapActions } from 'vuex'

import USER_EVENTS from '@/config/events/databaseAPI/usersEvents'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import usersActions from '@/store/users/actions.types'
import appActions from '@/store/app/actions.types'

import Button from '@/components/shared/CustomButton'
import EmployeeInfo from '@/components/PreferencesView/AdminPreferences/Employees/EmployeeInfo'
import ActionsCard from '@/components/shared/ActionsCard'
import EmployeeForm from '@/components/PreferencesView/AdminPreferences/Employees/EmployeeForm'
import DialogCard from '@/components/shared/DialogCard'
import setConfig from '@/components/PreferencesView/AdminPreferences/Employees/config'

export default {
  name: 'EmployeesAdmin',
  components: {
    DialogCard,
    EmployeeForm,
    ActionsCard,
    Button,
    EmployeeInfo,
  },
  data() {
    return {
      employeeToEdit: {},
      employeeToDelete: null,
    }
  },
  computed: {
    ...mapState('users', ['users', 'confirmationDeletionDialog']),
    ...mapState('usersView', ['selectedUser']),
    ...mapState('app', ['employeeFormDialog']),
    employees() {
      const allUsers = this.users
      return allUsers.filter(user => user._id !== 1 && user.deleted === 0)
    },
    config() {
      return setConfig(
        {
          isOpen: this.confirmationDeletionDialog.isOpen,
          employeeToDelete: this.employeeToDelete,
        },
        {
          closeDialog: this.switchConfirmationDeletionStatus,
          deleteEmployee: this.deleteEmployee,
          track: this.$track,
        }
      )
    },
  },
  methods: {
    ...mapActions('users', [
      usersActions.addUser,
      usersActions.deleteUser,
      usersActions.updateUser,
      usersActions.setConfirmationDeletionDialogStatus,
    ]),
    ...mapActions('app', [
      appActions.setEmployeeFormDialogStatus,
      appActions.addPendingSyncOperation,
    ]),
    enableFormEmployee(employee = null) {
      this.employeeToEdit = employee || {}
      this[appActions.setEmployeeFormDialogStatus]({ isOpen: true })
    },
    saveEmployee(employee) {
      if (employee._id) {
        this.saveEditedEmployee(employee)
        return
      }
      this.saveNewEmployee(employee)
    },
    saveEditedEmployee(employee) {
      rendererEventsService.send(USER_EVENTS.channel, {
        event: USER_EVENTS.events.update.name,
        data: { userId: employee._id, values: employee },
      })
    },
    saveNewEmployee(employee) {
      const max = this.users.reduce((prev, current) =>
        prev._id > current._id ? prev : current
      )._id
      const newEmployee = { _id: max + 1, ...employee }
      rendererEventsService.send(USER_EVENTS.channel, {
        event: USER_EVENTS.events.add.name,
        data: { employee: newEmployee },
      })
    },
    switchConfirmationDeletionStatus(isOpen, employeeId = null) {
      this.employeeToDelete = employeeId
      this[usersActions.setConfirmationDeletionDialogStatus](isOpen)
    },
    deleteEmployee(employeeId) {
      this.switchConfirmationDeletionStatus(false)
      if (!employeeId) {
        return
      }
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Preferences',
        screen: 'DeleteEmployeeConfirm',
        name: 'Confirm',
      })
      rendererEventsService.send(USER_EVENTS.channel, {
        event: USER_EVENTS.events.delete.name,
        data: { userId: employeeId },
      })
    },
    employeeListener(event, payload) {
      const userEvents = USER_EVENTS.events
      const replies = {
        [userEvents.add.replies.success]: () => {
          this.$track({
            type: 'system',
            action: 'add_employee',
            category: 'Preferences',
            screen: 'EmployeeForm',
            name: 'Close dialog',
          })
          this[usersActions.addUser](payload.data.employee)
          this[appActions.addPendingSyncOperation]()
        },
        [userEvents.add.replies.error]: () => {
          this.$track({
            type: 'system',
            action: 'error',
            category: 'Preferences',
            screen: 'EmployeeForm',
            name: 'Error adding employee',
          })
          notificationsService.showError(
            'notification.users.newUserError',
            this.$vuetify.lang
          )
        },
        [userEvents.update.replies.success]: () => {
          this.$track({
            type: 'system',
            action: 'update_employee',
            category: 'Preferences',
            screen: 'EmployeeForm',
            name: 'Close dialog',
          })
          this[usersActions.updateUser](payload.data)
          this[appActions.addPendingSyncOperation]()
        },
        [userEvents.update.replies.error]: () => {
          this.$track({
            type: 'system',
            action: 'error',
            category: 'Preferences',
            screen: 'EmployeeForm',
            name: 'Error updating employee',
          })
          notificationsService.showError(
            'notification.users.editUserError',
            this.$vuetify.lang
          )
        },
        [userEvents.delete.replies.success]: () => {
          this.$track({
            type: 'system',
            action: 'delete_employee',
            category: 'Preferences',
            screen: 'DeleteEmployeeConfirm',
            name: 'Close dialog',
          })
          const employeeIndex = this.users.indexOf(
            this.users.find(employee => employee._id === payload.data.userId)
          )
          this[usersActions.deleteUser](employeeIndex)
          this[appActions.addPendingSyncOperation]()
        },
        [userEvents.delete.replies.error]: () => {
          this.$track({
            type: 'system',
            action: 'error',
            category: 'Preferences',
            screen: 'DeleteEmployeeConfirm',
            name: 'Error deleting employee',
          })
          notificationsService.showError(
            'notification.users.deleteUserError',
            this.$vuetify.lang
          )
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  mounted() {
    rendererEventsService.subscribe(
      USER_EVENTS.replyChannel,
      this.employeeListener
    )
  },
  destroyed() {
    rendererEventsService.removeListener(
      USER_EVENTS.replyChannel,
      this.employeeListener
    )
  },
}
</script>
