<template>
  <div>
    <ActionsCard
      title="preferences.admin.restoreStock.title"
      icon="mdi-restore"
      :actions="actions"
    />
    <RestoreStockConfirmationDialog
      :restoreNegativeStock="restoreNegativeStock"
      @acceptRestore="restoreInventory"
    />
  </div>
</template>

<script>
import { mapActions, mapState } from 'vuex'

import STORE_INVENTORY_DB_API_EVENTS from '@/config/events/databaseAPI/storeInventoryEvents'
import ENTITIES_EVENTS from '@/config/events/databaseAPI/entitiesEvents'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import productsActions from '@/store/products/actions.types'
import appActions from '@/store/app/actions.types'

import ActionsCard from '@/components/shared/ActionsCard'
import RestoreStockConfirmationDialog from '@/components/PreferencesView/AdminPreferences/RestoreStockProducts/RestoreStockConfirmationDialog'

export default {
  name: 'RestoreStockProducts',
  components: { RestoreStockConfirmationDialog, ActionsCard },
  data() {
    return {
      actions: [
        {
          text: 'preferences.admin.restoreStock.all',
          event: this.restoreStockProducts,
        },
        {
          text: 'preferences.admin.restoreStock.negative',
          event: this.restoreNegativeStockProducts,
        },
      ],
      restoreNegativeStock: false,
    }
  },
  computed: {
    ...mapState('app', ['restoreStockConfirmationDialog']),
    ...mapState('usersView', ['selectedUser']),
  },
  methods: {
    ...mapActions('products', [productsActions.fetchProducts]),
    ...mapActions('app', [
      appActions.addPendingSyncOperation,
      appActions.setRestoreStockConfirmationDialogStatus,
    ]),
    restoreStockProducts() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Preferences',
        screen: 'Admin',
        name: 'Restore stock',
      })
      this[appActions.setRestoreStockConfirmationDialogStatus]({ isOpen: true })
      this.restoreNegativeStock = false
    },
    restoreNegativeStockProducts() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Preferences',
        screen: 'Admin',
        name: 'Restore negative stock',
      })
      this[appActions.setRestoreStockConfirmationDialogStatus]({ isOpen: true })
      this.restoreNegativeStock = true
    },
    restoreInventory() {
      rendererEventsService.send(STORE_INVENTORY_DB_API_EVENTS.channel, {
        event: STORE_INVENTORY_DB_API_EVENTS.events.restoreInventory.name,
        data: {
          onlyNegativeStock: this.restoreNegativeStock,
          username: this.selectedUser.name,
        },
      })
    },
    restoreStockListener(event, payload) {
      const replies = {
        [STORE_INVENTORY_DB_API_EVENTS.events.restoreInventory.replies
          .success]: () => {
          this.$track({
            type: 'system',
            action: 'restore_inventory',
            category: 'Preferences',
            screen: 'RestoreStockConfirmationDialog',
            name: 'Close dialog',
          })
          if (payload.data.values.length) {
            this[appActions.addPendingSyncOperation]()
            this.reloadProducts()
          }
          this[appActions.setRestoreStockConfirmationDialogStatus]({
            isOpen: false,
          })
          notificationsService.showSuccess(
            payload.data.message,
            this.$vuetify.lang
          )
        },
        [STORE_INVENTORY_DB_API_EVENTS.events.restoreInventory.replies
          .error]: () => {
          this.$track({
            type: 'system',
            action: 'error',
            category: 'Preferences',
            screen: 'RestoreStockConfirmationDialog',
            name: 'Error restoring stock',
          })
          notificationsService.showError(
            payload.data.error.message,
            this.$vuetify.lang
          )
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
    reloadProducts() {
      rendererEventsService.send(ENTITIES_EVENTS.channel, {
        event: ENTITIES_EVENTS.events.getAllByEntities.name,
        data: {
          entitiesToGet: [
            'storeInventory',
            'superCategories',
            'genericCategories',
            'byWeightHomeCodes',
            'airtimeProviders',
            'airtimeServices',
          ],
          replyName: 'fetchProducts',
        },
      })
    },
    entitiesListener(event, payload) {
      const getAllReplies = ENTITIES_EVENTS.events.getAllByEntities.replies
      const replies = {
        [`${getAllReplies.success}-fetchProducts`]: () =>
          this[productsActions.fetchProducts](payload.data),
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  created() {
    rendererEventsService.subscribe(
      STORE_INVENTORY_DB_API_EVENTS.replyChannel,
      this.restoreStockListener
    )
    rendererEventsService.subscribe(
      ENTITIES_EVENTS.replyChannel,
      this.entitiesListener
    )
  },
  beforeDestroy() {
    rendererEventsService.removeListener(
      STORE_INVENTORY_DB_API_EVENTS.replyChannel,
      this.restoreStockListener
    )
    rendererEventsService.removeListener(
      ENTITIES_EVENTS.replyChannel,
      this.entitiesListener
    )
  },
}
</script>

<style scoped lang="scss">
div {
  height: 100%;
}
</style>
