<template>
  <DialogCard :config="componentConfig.dialogData">
    <Form :config="componentConfig" />
  </DialogCard>
</template>

<script>
import { mapState, mapActions } from 'vuex'

import AIRTIME_API_EVENTS from '@/config/events/airtime'

import { cleanObjectObserver } from '@/tools/data'
import { getNow } from '@/tools/dates'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import airtimeServicesActions from '@/store/airtimeServices/actions.types'

import setConfig from '@/components/AddAirtimeServicesBalance/config'
import DialogCard from '@/components/shared/DialogCard'
import Form from '@/components/shared/Form'

export default {
  name: 'AddAirtimeServicesBalance',
  components: { DialogCard, Form },
  data() {
    return {
      inputs: {},
      validators: { inputs: {} },
      addingBalance: false,
    }
  },
  computed: {
    ...mapState('airtimeServices', [
      'addAirtimeServicesBalanceDialog',
      'banks',
    ]),
    ...mapState('account', { accountData: state => state.data }),
    ...mapState('usersView', ['selectedUser']),
    componentConfig() {
      return setConfig(
        {
          opened: this.addAirtimeServicesBalanceDialog.isOpen,
          inputs: this.inputs,
          v: this.$v.inputs,
          bankItems: this.banks.map(bank => bank.account_name),
          isAcceptButtonDisabled: this.$v.inputs.$invalid,
        },
        {
          closeDialog: this.closeDialog,
          loadBalance: this.addAirtimeServicesBalance,
          track: this.$track,
        }
      )
    },
  },
  methods: {
    ...mapActions('airtimeServices', [
      airtimeServicesActions.setAddAirtimeServicesBalanceDialogStatus,
    ]),
    setProperties: function() {
      const now = getNow(false).split(' ')
      this.componentConfig.fields.forEach(field => {
        if (field.id === 'depositDate') {
          this.$set(this.inputs, field.id, now[0])
        } else if (field.id === 'depositTime') {
          this.$set(this.inputs, field.id, now[1].substring(0, 5))
        } else {
          this.$set(this.inputs, field.id, '')
        }
        if (field.validators)
          this.$set(this.validators.inputs, field.id, {
            ...cleanObjectObserver(field.validators),
          })
      })
    },
    addAirtimeServicesBalance() {
      if (this.addingBalance === true) return
      if (this.$v.inputs.$invalid) {
        Object.keys(this.inputs).forEach(key => this.$v.inputs[key].$touch())
        return
      }
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Preferences',
        screen: 'AddAirtimeServicesBalance',
        name: 'Submit',
      })
      this.addingBalance = true
      const posData = JSON.parse(JSON.stringify(this.accountData))
      delete posData.country
      rendererEventsService.send(AIRTIME_API_EVENTS.channel, {
        event: AIRTIME_API_EVENTS.events.loadBalance.name,
        data: {
          inputs: this.inputs,
          posData: posData,
          country: this.accountData.country.phoneCode,
        },
      })
    },
    closeDialog() {
      Object.keys(this.inputs).forEach(key => this.$v.inputs[key].$reset())
      Object.keys(this.inputs).forEach(key => (this.inputs[key] = ''))
      this[airtimeServicesActions.setAddAirtimeServicesBalanceDialogStatus]({
        isOpen: false,
      })
    },
  },
  validations() {
    return this.validators
  },
  created() {
    rendererEventsService.subscribe(
      AIRTIME_API_EVENTS.replyChannel,
      (event, payload) => {
        const replies = {
          [AIRTIME_API_EVENTS.events.loadBalance.replies.success]: () => {
            this.$track({
              type: 'system',
              action: 'load_balance',
              category: 'Preferences',
              screen: 'AddAirtimeServicesBalance',
              name: 'Save airtime services purchase',
            })
            rendererEventsService.send(AIRTIME_API_EVENTS.channel, {
              event: AIRTIME_API_EVENTS.events.saveAirtimeServicesPurchase.name,
              data: {
                inputs: this.inputs,
                userId: this.selectedUser.id,
              },
            })
            notificationsService.showSuccess(payload.data.result, null, {
              timeout: 10000,
            })
          },
          [AIRTIME_API_EVENTS.events.loadBalance.replies.error]: () => {
            this.$track({
              type: 'system',
              action: 'error',
              category: 'Preferences',
              screen: 'AddAirtimeServicesBalance',
              name: 'Error loading balance',
            })
            notificationsService.showError(payload.data.error)
            this.addingBalance = false
            this.closeDialog()
          },
          [AIRTIME_API_EVENTS.events.saveAirtimeServicesPurchase.replies
            .success]: () => {
            this.$track({
              type: 'system',
              action: 'save_airtime_purchase',
              category: 'Preferences',
              screen: 'AddAirtimeServicesBalance',
              name: 'Close dialog',
            })
            this.addingBalance = false
            this.closeDialog()
          },
          [AIRTIME_API_EVENTS.events.saveAirtimeServicesPurchase.replies
            .error]: () => {
            this.addingBalance = false
            this.$track({
              type: 'system',
              action: 'error',
              category: 'Preferences',
              screen: 'AddAirtimeServicesBalance',
              name: 'Error saving airtime purchase',
            })
            this.closeDialog()
          },
        }
        if (payload.event in replies) replies[payload.event]()
      }
    )
  },
  mounted() {
    this.setProperties()
  },
  beforeDestroy() {
    rendererEventsService.removeAllListeners(AIRTIME_API_EVENTS.replyChannel)
  },
}
</script>
