const MAX_SIZE = 180
const MAX_WIDTH = 800
const MAX_HEIGHT = 800

const compress = file => {
  return new Promise(resolve => {
    if (!file || !file.type || !file.type.startsWith('image/')) {
      resolve(null)
    }
    const reader = new FileReader()
    reader.onload = event => {
      const img = new Image()
      img.onload = () => onloadImage(resolve, img)
      img.onerror = () => resolve(null)
      img.src = event.target.result
    }
    reader.onerror = () => resolve(null)
    reader.readAsDataURL(file)
  })
}

const onloadImage = (resolve, img) => {
  const canvas = document.createElement('canvas')
  const scale = Math.min(MAX_WIDTH / img.width, MAX_HEIGHT / img.height, 1)
  canvas.width = img.width * scale
  canvas.height = img.height * scale
  const ctx = canvas.getContext('2d')
  ctx.drawImage(img, 0, 0, canvas.width, canvas.height)
  let quality = 0.9
  tryCompress(resolve, canvas, quality)
}

const tryCompress = (resolve, canvas, quality) => {
  canvas.toBlob(
    blob => {
      if (!blob) return resolve(null)
      if (blob.size / 1024 <= MAX_SIZE || quality <= 0.3) {
        const reader2 = new FileReader()
        reader2.onloadend = () => {
          resolve({
            dataUrl: reader2.result,
            blob,
            sizeKB: (blob.size / 1024).toFixed(2),
            quality: quality.toFixed(2),
          })
        }
        reader2.readAsDataURL(blob)
      } else {
        quality -= 0.1
        tryCompress(resolve, canvas, quality)
      }
    },
    'image/jpeg',
    quality
  )
}

export default {
  compress,
}
