<template>
  <ScrollContainer
    :height="`${cardHeight}px`"
    :scroll-active-style="{ 'margin-right': '-5px' }"
  >
    <div v-if="showAll">
      <FormattedText
        type="text-subtitle-1"
        intl
        value="preferences.profile.title"
        class="text-left mb-4"
        className="font-weight-bold"
      />
      <v-card class="" :style="`width: 98%;`" flat>
        <Form :config="formConfig" />
      </v-card>
    </div>
  </ScrollContainer>
</template>

<script>
import { mapState, mapActions } from 'vuex'
import { isNil } from 'ramda'

import { testMode } from '@/config/env'
import storeTypes from '@/config/storeTypes'
import USER_INFORMATION_DB_API_EVENTS from '@/config/events/databaseAPI/userInformationEvents'
import countries from '@/config/countries'

import { cleanObjectObserver } from '@/tools/data'

import imageTools from '@/tools/image'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import accountActions from '@/store/account/actions.types'
import appActions from '@/store/app/actions.types'

import FormattedText from '@/components/shared/FormattedText'
import Form from '@/components/shared/Form2Columns'
import setFormConfig from '@/components/PreferencesView/ProfilePreferences/config'
import ScrollContainer from '@/components/shared/ScrollContainer'

export default {
  name: 'ProfilePreferences',
  components: { ScrollContainer, FormattedText, Form },
  props: {
    config: {
      type: Object,
      required: true,
    },
  },
  data() {
    return {
      inputs: {},
      validators: { inputs: {} },
    }
  },
  computed: {
    ...mapState('account', { accountData: state => state.data }),
    showAll() {
      return this.config.show
    },
    country() {
      return this.accountData.country.localeIsoCode
    },
    states() {
      return countries[this.country].states
    },
    towns() {
      return countries[this.country].getTowns(this.inputs.state)
    },
    formConfig() {
      return setFormConfig(
        {
          inputs: this.inputs,
          v: this.$v.inputs,
          country: this.country,
          states: this.states,
          towns: this.towns,
          storeTypes:
            this.country in storeTypes
              ? storeTypes[this.country]
              : storeTypes['default'],
        },
        {}
      )
    },
    cardHeight() {
      if (!isNil(testMode)) return 600
      return (
        document.getElementsByClassName('preferences')[0].offsetHeight * 0.85
      )
    },
  },
  methods: {
    ...mapActions('account', [accountActions.setOwnerAndStoreNames]),
    ...mapActions('app', [appActions.addPendingSyncOperation]),
    setProperties() {
      this.formConfig.fields.forEach(field => {
        const isVisible = Object.hasOwn(field, 'visible') ? field.visible : true
        const isHidden = Object.hasOwn(field, 'hideCol') ? field.hideCol : false
        if (isVisible && !isHidden) {
          !isNil(field.defaultValue)
            ? this.$set(this.inputs, field.id, field.defaultValue)
            : field.type === 'fileInput'
            ? this.$set(this.inputs, field.id, undefined)
            : this.$set(this.inputs, field.id, '')
          if (field.validators)
            this.$set(this.validators.inputs, field.id, {
              ...cleanObjectObserver(field.validators),
            })
        }
      })
    },
    async saveProfile() {
      if (this.$v.inputs.$invalid) {
        Object.keys(this.inputs).forEach(key => {
          if (key in this.$v.inputs) this.$v.inputs[key].$touch()
        })
        this.$root.$emit('profileWasSaved', 'profile', false)
        notificationsService.showError(
          'preferences.profile.profileSavedError',
          this.$vuetify.lang
        )
        return
      }
      const imageResult = await imageTools.compress(this.inputs.storeLogo)
      const imageBase64 = imageResult ? imageResult.dataUrl.split(',')[1] : null
      delete this.inputs.storeLogo
      rendererEventsService.send(USER_INFORMATION_DB_API_EVENTS.channel, {
        event: USER_INFORMATION_DB_API_EVENTS.events.updateProfile.name,
        data: {
          inputs: { imageBase64, ...this.inputs },
        },
      })
    },
    loadUserInfo() {
      rendererEventsService.send(USER_INFORMATION_DB_API_EVENTS.channel, {
        event: USER_INFORMATION_DB_API_EVENTS.events.getAll.name,
      })
    },
  },
  validations() {
    return this.validators
  },
  watch: {
    'inputs.state': function(newValue, oldValue) {
      if (this.inputs.state === null) {
        this.inputs.state = ''
        this.inputs.town = ''
      } else if (this.inputs.state && this.inputs.state !== '') {
        if (this.towns) {
          this.inputs.town = oldValue === '' ? this.inputs.town : ''
        }
      }
    },
  },
  mounted() {
    rendererEventsService.subscribe(
      USER_INFORMATION_DB_API_EVENTS.replyChannel,
      async (event, payload) => {
        const userEventsReplies = USER_INFORMATION_DB_API_EVENTS.events
        const replies = {
          [userEventsReplies.getAll.replies.success]: () => {
            this.inputs.storeName = payload.data[0].store_name
            this.inputs.state =
              payload.data[0].store_state === ''
                ? payload.data[0].store_state
                : parseInt(payload.data[0].store_state)
            this.inputs.town = this.towns.includes(payload.data[0].store_town)
              ? payload.data[0].store_town
              : ''
            this.inputs.zipCode = parseInt(payload.data[0].store_postal_code)
            this.inputs.completeAddress = payload.data[0].store_address
            this.inputs.name = payload.data[0].name
            this.inputs.storePhone = payload.data[0].mobile_phone
            this.inputs.landlinePhone = payload.data[0].store_landline_phone
            this.inputs.email = payload.data[0].user_mail
            this.inputs.storetype = payload.data[0].store_type
            this.inputs.storeSize = payload.data[0].store_size
            this.inputs.coolersNumber = payload.data[0].store_coolers_number
          },
          [userEventsReplies.updateProfile.replies.success]: () => {
            this[appActions.addPendingSyncOperation]()
            this[accountActions.setOwnerAndStoreNames]({
              storeName: this.inputs.storeName,
              ownerName: this.inputs.name,
              storeImage: payload.data.storeImage,
              storeAddress: this.inputs.completeAddress,
              storePostalCode: this.inputs.zipCode,
              storeCity: this.inputs.city,
              storeTown: this.inputs.town,
              storeState: this.inputs.state,
              storeLandlinePhone: this.inputs.landlinePhone,
              storePhone: this.inputs.storePhone,
            })
            this.$root.$emit('profileWasSaved', 'profile', true)
          },
        }
        if (payload.event in replies) replies[payload.event]()
      }
    )
    this.loadUserInfo()
    this.$root.$on('save-profile', () => this.saveProfile())
    this.setProperties()
  },
  beforeDestroy() {
    this.$root.$off('save-profile')
    rendererEventsService.removeAllListeners(
      USER_INFORMATION_DB_API_EVENTS.replyChannel
    )
  },
}
</script>
