const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.isOpen,
    icon: 'mdi-restore',
    title: state.restoreNegativeStock
      ? 'preferences.admin.restoreStock.negative'
      : 'preferences.admin.restoreStock.all',
    titleBackground: '#white',
    titleColor: 'textPrimary',
    messages: [
      state.restoreNegativeStock
        ? 'preferences.admin.restoreStock.confirmationNegative'
        : 'preferences.admin.restoreStock.confirmationAll',
    ],
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    maxWidth: 600,
    onClickCancel: () => methods.closeDialog(),
    onClickAccept: () => methods.acceptRestore(),
  },
})

export default setConfig
