export default {
  airtime: {
    countries: ['MX'],
    pos: [],
  },
}

export const useFeature = (account, feature) => {
  const { pos, country } = account
  const { countries } = feature
  const featurePos = feature['pos']
  const limitedCountries = countries.length > 0
  const limitedPos = featurePos.length > 0

  if (limitedPos && limitedCountries)
    return countries.includes(country.localeIsoCode) && featurePos.includes(pos)
  if (limitedCountries) return countries.includes(country.localeIsoCode)
  if (limitedPos) return featurePos.includes(pos)
}
