<template>
  <div class="d-flex flex-wrap">
    <template v-for="item in list">
      <v-tooltip bottom v-if="item.show" :key="item.id" max-width="250px">
        <template v-slot:activator="{ on, attrs }">
          <v-chip
            v-bind="attrs"
            v-on="on"
            color="accent"
            :outlined="!listEnabled[item.id]"
            :disabled="disabled"
            @click="clickFunction(item.id)"
          >
            <v-avatar left>
              <v-icon :color="!listEnabled[item.id] ? '' : 'white'">{{
                item.icon
              }}</v-icon>
            </v-avatar>
            <FormattedText
              :value="item.title"
              intl
              :color="!listEnabled[item.id] ? '' : 'white'"
              type="text-body-2"
            />
          </v-chip>
        </template>
        <span>{{ $vuetify.lang.t(`$vuetify.${item.description}`) }}</span>
      </v-tooltip>
    </template>
  </div>
</template>

<script>
import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'ChipList',
  components: {
    FormattedText,
  },
  props: {
    list: {
      type: Array,
      required: true,
    },
    listEnabled: {
      type: Object,
    },
    clickFunction: {
      type: Function,
    },
    disabled: {
      type: Boolean,
      default: false,
    },
  },
}
</script>
