<template>
  <div>
    <FormattedText
      type="text-subtitle-1"
      intl
      value="preferences.pays.addMarginTicket"
      class="text-left mb-4"
      className="font-weight-bold"
    />
    <v-switch
      :input-value="addMarginTicket"
      hide-details
      inset
      @change="changeStatus"
      :label="getTranslatedText('shared.yes')"
    />
  </div>
</template>

<script>
import { mapState, mapActions } from 'vuex'

import { getTranslatedText } from '@/tools/data'

import appActions from '@/store/app/actions.types'

import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'AddMarginTicket',
  components: { FormattedText },
  computed: {
    ...mapState('app', ['addMarginTicket']),
  },
  methods: {
    getTranslatedText,
    ...mapActions('app', [appActions.setAddMarginTicketStatus]),
    changeStatus(event) {
      this.$track({
        type: 'interaction',
        action: 'change',
        category: 'Preferences',
        screen: 'Pays',
        name: 'Change ticket margin',
      })
      this[appActions.setAddMarginTicketStatus](event)
    },
  },
}
</script>
