<template>
  <v-card
    flat
    class="actions-card align-self-stretch"
    color="cardBackgroundSecondary"
    height="100%"
  >
    <v-card-title>
      <v-icon v-if="!!icon" class="mr-1">{{ icon }}</v-icon>
      <FormattedText
        type="text-subtitle-1"
        :value="title"
        intl
        class-name="font-weight-medium"
      />
    </v-card-title>
    <v-card-text class="d-flex flex-column">
      <v-list dense class="transparent" v-if="actions && actions.length">
        <v-list-item-group>
          <v-list-item
            v-for="(action, i) in actions"
            :key="i"
            active-class="action-card__btn--active"
          >
            <v-list-item-content
              @click="action.event(action.id)"
              class="action-card__btn"
            >
              <FormattedText
                :value="action.text"
                intl
                color="primary"
                class-name="action-card__btn"
              />
            </v-list-item-content>
          </v-list-item>
        </v-list-item-group>
      </v-list>
      <slot />
    </v-card-text>
  </v-card>
</template>

<script>
import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'ActionsCard',
  components: { FormattedText },
  props: {
    title: {
      type: String,
      default: '',
    },
    actions: {
      type: Array,
      default: () => [],
    },
    icon: {
      type: String,
      default: '',
    },
  },
}
</script>

<style scoped lang="scss">
.action-card {
  &__btn {
    font-size: 14px;
    text-transform: uppercase;
    letter-spacing: 0.0892857143em;
    font-weight: 500;
    border-radius: 4px;
    &--active {
      &::before {
        opacity: 0;
      }
      &:focus::before {
        opacity: 0;
      }
    }
    :deep(span) {
      line-height: 1.5 !important;
    }
  }
}
</style>
