<template>
  <ScrollContainer height="auto" :max-height="`${cardHeight}px`">
    <v-card flat color="cardBackgroundPrimary">
      <v-card-title>
        <FormattedText
          type="text-h4"
          value="preferences.information.title"
          intl
          class-name="font-weight-medium"
        />
      </v-card-title>
      <v-card-subtitle>
        <FormattedText value="preferences.information.subtitle" intl />
      </v-card-subtitle>
      <v-card-text class="pt-2">
        <v-row>
          <v-col cols="12" class="d-flex justify-space-between align-center">
            <FormattedText
              type="text-h5"
              value="preferences.information.systemVersions"
              intl
              class-name="font-weight-medium"
            />
            <v-btn
              outlined
              small
              @click="checkForUpdates"
              :disabled="!hasInternetConnection || checkingAppVersion"
              :loading="checkingAppVersion"
            >
              <v-icon class="mr-2">mdi-update</v-icon>
              <FormattedText
                value="preferences.information.checkUpdates"
                intl
              />
            </v-btn>
          </v-col>
          <v-col
            v-for="version in generalVersions"
            :key="version.name"
            cols="6"
            md="4"
          >
            <VersionCard :version="version" />
          </v-col>
        </v-row>
        <v-row>
          <v-col cols="12">
            <FormattedText
              type="text-h5"
              value="preferences.information.systemStatus"
              intl
              class-name="font-weight-medium"
            />
          </v-col>
          <v-col cols="12">
            <v-card flat outlined>
              <v-card-text class="py-6">
                <StatusRow
                  icon="mdi-web"
                  color="info"
                  text="preferences.information.internetConnection"
                >
                  <v-chip
                    :color="hasInternetConnection ? 'primary' : 'error'"
                    class="font-weight-bold"
                  >
                    <FormattedText
                      color="white"
                      :value="
                        hasInternetConnection
                          ? 'preferences.information.connected'
                          : 'preferences.information.disconnected'
                      "
                      intl
                    />
                  </v-chip>
                </StatusRow>
                <StatusRow
                  icon="mdi-checkbox-multiple-marked-circle-outline"
                  color="primary"
                  text="preferences.information.pendingSyncOps"
                >
                  <FormattedText
                    type="text-subtitle-1"
                    :value="pendingSyncOps ? pendingSyncOps.toString() : '0'"
                    class-name="font-weight-bold"
                  />
                </StatusRow>
              </v-card-text>
            </v-card>
          </v-col>
        </v-row>
      </v-card-text>
    </v-card>
  </ScrollContainer>
</template>

<script>
import { mapState } from 'vuex'
import { isNil } from 'ramda'

import { testMode, databaseVersion } from '@/config/env'
import POS_DB_API_EVENTS from '@/config/events/databaseAPI/posEvents'
import BY_WEIGHT_HOME_CODES_DB_API_EVENTS from '@/config/events/databaseAPI/byWeightHomeCodesEvents'
import UPDATER_EVENTS from '@/config/events/updater'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import ScrollContainer from '@/components/shared/ScrollContainer'
import FormattedText from '@/components/shared/FormattedText'
import VersionCard from '@/components/PreferencesView/InfoPreferences/VersionCard'
import StatusRow from '@/components/PreferencesView/InfoPreferences/StatusRow'

export default {
  name: 'InfoPreferences',
  components: { ScrollContainer, FormattedText, VersionCard, StatusRow },
  data() {
    return {
      hasInternetConnection: navigator.onLine,
      checkingAppVersion: false,
      generalVersions: [
        {
          icon: 'mdi-application-outline',
          name: 'preferences.information.tiendatekVersion',
          version: process.env.VUE_APP_VERSION,
        },
        {
          icon: 'mdi-fridge-outline',
          name: 'preferences.information.MLPVersion',
          version: null,
        },
        {
          icon: 'mdi-truck',
          name: 'preferences.information.MLSVersion',
          version: null,
        },
        {
          icon: 'mdi-database-outline',
          name: 'preferences.information.dbVersion',
          version: databaseVersion.toString(),
        },
        {
          icon: 'mdi-barcode',
          name: 'preferences.information.homesVersion',
          version: null,
        },
        {
          icon: 'mdi-cellphone',
          name: 'preferences.information.airtimeServicesProviders',
          version: null,
        },
      ],
    }
  },
  computed: {
    ...mapState('app', ['pendingSyncOps']),
    cardHeight() {
      if (!isNil(testMode)) return 600
      return (
        document.getElementsByClassName('preferences')[0].offsetHeight * 0.9
      )
    },
  },
  methods: {
    checkInternetConnection() {
      this.hasInternetConnection = navigator.onLine
    },
    checkForUpdates() {
      this.checkingAppVersion = true
      rendererEventsService.send(UPDATER_EVENTS.channel, {
        event: UPDATER_EVENTS.events.checkForUpdatesManual.name,
      })
    },
    posListener(event, payload) {
      const events = POS_DB_API_EVENTS.events
      const replies = {
        [events.getAll.replies.success]: () => {
          const data = payload.data[0]
          this.generalVersions[1].version = data.mlp_version.toString()
          this.generalVersions[2].version = data.mls_version.toString()
          this.generalVersions[5].version = data.airtime_providers_version.toString()
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
    homesListener(event, payload) {
      const events = BY_WEIGHT_HOME_CODES_DB_API_EVENTS.events
      const replies = {
        [events.getVersion.replies.success]: () => {
          const data = payload.version
          this.generalVersions[4].version = data.toString()
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
    updateListener(event, payload) {
      const events = UPDATER_EVENTS.events
      const replies = {
        [events.checkForUpdatesManual.replies.success]: () => {
          this.checkingAppVersion = false
        },
        [events.checkForUpdatesManual.replies.error]: () => {
          this.checkingAppVersion = false
          notificationsService.showError(
            'notification.preferences.errorCheckUpdates',
            this.$vuetify.lang
          )
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  created() {
    window.addEventListener('online', this.checkInternetConnection)
    window.addEventListener('offline', this.checkInternetConnection)
    rendererEventsService.subscribe(
      POS_DB_API_EVENTS.replyChannel,
      this.posListener
    )
    rendererEventsService.subscribe(
      BY_WEIGHT_HOME_CODES_DB_API_EVENTS.replyChannel,
      this.homesListener
    )
    rendererEventsService.subscribe(
      UPDATER_EVENTS.replyChannel,
      this.updateListener
    )
  },
  mounted() {
    rendererEventsService.send(POS_DB_API_EVENTS.channel, {
      event: POS_DB_API_EVENTS.events.getAll.name,
    })
    rendererEventsService.send(BY_WEIGHT_HOME_CODES_DB_API_EVENTS.channel, {
      event: BY_WEIGHT_HOME_CODES_DB_API_EVENTS.events.getVersion.name,
    })
  },
  beforeDestroy() {
    window.removeEventListener('online', this.checkInternetConnection)
    window.removeEventListener('offline', this.checkInternetConnection)
    rendererEventsService.removeListener(
      POS_DB_API_EVENTS.replyChannel,
      this.posListener
    )
    rendererEventsService.removeListener(
      BY_WEIGHT_HOME_CODES_DB_API_EVENTS.replyChannel,
      this.homesListener
    )
    rendererEventsService.removeListener(
      UPDATER_EVENTS.replyChannel,
      this.updateListener
    )
  },
}
</script>
