<template>
  <div>
    <ActionsCard
      title="preferences.admin.airtimeServices"
      icon="mdi-cellphone-charging"
      :actions="actions"
    />
    <AddAirtimeServicesBalanceDialog
      v-if="addAirtimeServicesBalanceDialog.isOpen"
    />
  </div>
</template>

<script>
import { mapState, mapActions } from 'vuex'

import { depositsInfoWeb } from '@/config/env'

import airtimeServicesActions from '@/store/airtimeServices/actions.types'

import ActionsCard from '@/components/shared/ActionsCard'
import AddAirtimeServicesBalanceDialog from '@/components/AddAirtimeServicesBalance'

export default {
  name: 'AirtimeServicesAdmin',
  components: {
    ActionsCard,
    AddAirtimeServicesBalanceDialog,
  },
  data() {
    return {
      actions: [
        {
          text: 'preferences.admin.airtimeServicesPurchase',
          event: this.airtimeServicesPurchase,
        },
        {
          text: 'preferences.admin.airtimeDepositsInfo',
          event: this.openAirtimeDepositsInfo,
        },
      ],
    }
  },
  computed: {
    ...mapState('airtimeServices', ['addAirtimeServicesBalanceDialog']),
  },
  methods: {
    ...mapActions('airtimeServices', [
      airtimeServicesActions.setAddAirtimeServicesBalanceDialogStatus,
    ]),
    airtimeServicesPurchase() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Preferences',
        screen: 'Admin',
        name: 'Purchase airtime services',
      })
      this[airtimeServicesActions.setAddAirtimeServicesBalanceDialogStatus]({
        isOpen: true,
      })
    },
    openAirtimeDepositsInfo() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Preferences',
        screen: 'Admin',
        name: 'Show airtime deposits info',
      })
      window.open(depositsInfoWeb, '_blank')
    },
  },
}
</script>

<style scoped lang="scss">
div {
  height: 100%;
}
</style>
