const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.isOpen,
    icon: 'mdi-alert-circle',
    title: 'preferences.admin.deleteEmployee',
    titleBackground: '#white',
    titleColor: 'textPrimary',
    messages: ['preferences.admin.deleteEmployeeConfirmation'],
    extraValuesMessages: [
      state.employeeToDelete ? state.employeeToDelete.name : '',
    ],
    persistent: true,
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    maxWidth: 500,
    onClickCancel: () => {
      methods.track({
        type: 'interaction',
        action: 'click',
        category: 'Preferences',
        screen: 'DeleteEmployeeConfirm',
        name: 'Cancel',
      })
      methods.closeDialog(false)
    },
    onClickAccept: () => methods.deleteEmployee(state.employeeToDelete._id),
  },
})

export default setConfig
