<template>
  <DialogCard :config="componentConfig.dialogData">
    <Form :config="componentConfig" />
  </DialogCard>
</template>

<script>
import { mapState, mapActions } from 'vuex'

import AUTH_EVENTS from '@/config/events/auth'

import { cleanObjectObserver } from '@/tools/data'

import notificationsService from '@/services/renderer/notifications'
import redererEventsService from '@/services/renderer/rendererEvents'

import usersActions from '@/store/users/actions.types'
import appActions from '@/store/app/actions.types'

import setConfig from '@/components/PreferencesView/AdminPreferences/AdminPasswordDialog/config'
import DialogCard from '@/components/shared/DialogCard'
import Form from '@/components/shared/Form'

export default {
  name: 'AdminPasswordDialog',
  components: { DialogCard, Form },
  data() {
    return {
      inputs: {},
      validators: { inputs: {} },
    }
  },
  computed: {
    ...mapState('app', ['adminPasswordDialog']),
    componentConfig() {
      return setConfig(
        {
          inputs: this.inputs,
          v: this.$v.inputs,
          isOpen: this.adminPasswordDialog.isOpen,
        },
        {
          closeDialog: this.closeDialog,
          checkPassword: this.checkPassword,
          track: this.$track,
        }
      )
    },
  },
  validations() {
    return this.validators
  },
  methods: {
    ...mapActions('users', [usersActions.checkAdminPassword]),
    ...mapActions('app', [appActions.setAdminPasswordDialogStatus]),
    setProperties: function() {
      this.componentConfig.fields.forEach(field => {
        this.$set(this.inputs, field.id, '')
        if (field.validators)
          this.$set(this.validators.inputs, field.id, {
            ...cleanObjectObserver(field.validators),
          })
      })
    },
    checkPassword: async function() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Preferences',
        screen: 'AdminPasswordDialog',
        name: 'Submit',
      })
      if (this.$v.inputs.$invalid) {
        Object.keys(this.inputs).forEach(key => this.$v.inputs[key].$touch())
        return
      }
      redererEventsService.send(AUTH_EVENTS.channel, {
        event: AUTH_EVENTS.events.adminPasswordIsValid.name,
        data: { password: this.inputs.password },
      })
    },
    closeDialog() {
      Object.keys(this.inputs).forEach(key => this.$v.inputs[key].$reset())
      Object.keys(this.inputs).forEach(key => (this.inputs[key] = ''))
      this[appActions.setAdminPasswordDialogStatus](false)
    },
  },
  created() {
    redererEventsService.subscribe(
      AUTH_EVENTS.replyChannel,
      (event, payload) => {
        const replies = {
          [AUTH_EVENTS.events.adminPasswordIsValid.replies.error]: () => {
            this.$track({
              type: 'system',
              action: 'error',
              category: 'Preferences',
              screen: 'AdminPasswordDialog',
              name: 'Error checking password',
            })
            this.closeDialog()
            this.$emit('adminPasswordIntroduced')
          },
          [AUTH_EVENTS.events.adminPasswordIsValid.replies.isValid]: () => {
            this.closeDialog()
            this.$emit('adminPasswordIntroduced')
            this.$track({
              type: 'system',
              action: 'check_password',
              category: 'Preferences',
              screen: 'AdminPasswordDialog',
              name: 'Close dialog',
            })
          },
          [AUTH_EVENTS.events.adminPasswordIsValid.replies.isNotValid]: () => {
            notificationsService.showError(
              'notification.users.incorrectPassword',
              this.$vuetify.lang
            )
            this.$track({
              type: 'system',
              action: 'check_password',
              category: 'Preferences',
              screen: 'AdminPasswordDialog',
              name: 'Show password invalid feedback',
            })
          },
        }
        if (payload.event in replies) replies[payload.event]()
      }
    )
  },
  mounted: async function() {
    this.setProperties()
  },
  beforeDestroy() {
    redererEventsService.removeAllListeners(AUTH_EVENTS.replyChannel)
  },
}
</script>

