<template>
  <DialogCard :config="config.dialogData">
    <Form :config="config" class="mb-1" />
    <FormattedText
      intl
      value="preferences.admin.permissionsEmployee"
      className="ml-1"
    />
    <ChipList
      :list="permissions"
      :listEnabled="inputs"
      :clickFunction="addOrRemovePermission"
      class="mt-2 employee-permissions__chips"
    />
  </DialogCard>
</template>

<script>
import { mapActions, mapState } from 'vuex'

import employeePermissions from '@/config/employeePermissions'

import { cleanObjectObserver } from '@/tools/data'

import appActions from '@/store/app/actions.types'

import ChipList from '@/components/shared/ChipList'
import Form from '@/components/shared/Form'
import DialogCard from '@/components/shared/DialogCard'
import FormattedText from '@/components/shared/FormattedText'
import setConfig from '@/components/PreferencesView/AdminPreferences/Employees/EmployeeForm/config'

export default {
  name: 'EmployeeForm',
  components: { FormattedText, DialogCard, Form, ChipList },
  props: {
    employeeToEdit: {
      type: Object,
      default: () => ({}),
    },
  },
  data() {
    return {
      validators: { inputs: {} },
      inputs: {
        name: '',
        password: '',
        access_permission: 0,
        inventory_permission: 0,
        register_adjust_permission: 0,
        sales_purchases_return_permission: 0,
        expenses_permission: 0,
        cash_in_out_permission: 0,
        loyalty_program_permission: 1,
        report_permission: 0,
        promotion_permission: 0,
        operations_permission: 0,
        deleted: 0,
      },
    }
  },
  computed: {
    permissions() {
      return employeePermissions
    },
    ...mapState('app', ['employeeFormDialog']),
    config() {
      return setConfig(
        {
          showDialog: this.employeeFormDialog.isOpen,
          inputs: this.inputs,
          v: this.$v.inputs,
        },
        {
          closeDialogForm: this.closeDialogForm,
          saveEmployee: this.saveEmployee,
          track: this.$track,
        }
      )
    },
  },
  methods: {
    ...mapActions('app', [appActions.setEmployeeFormDialogStatus]),
    setProperties() {
      this.config.fields.forEach(field => {
        if (field.validators) {
          this.$set(this.validators.inputs, field.id, {
            ...cleanObjectObserver(field.validators),
          })
        }
      })
    },
    addOrRemovePermission(itemId) {
      this.inputs[itemId] = this.inputs[itemId] === 0 ? 1 : 0
    },
    closeDialogForm() {
      this[appActions.setEmployeeFormDialogStatus]({ isOpen: false })
    },
    saveEmployee() {
      if (this.$v.$invalid) {
        this.$v.$touch()
        return
      }
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Preferences',
        screen: 'EmployeeForm',
        name: 'Submit',
      })
      this.$emit('saveEmployee', this.inputs)
      this.closeDialogForm()
    },
  },
  validations() {
    return this.validators
  },
  beforeMount() {
    Object.keys(this.employeeToEdit).forEach(key => {
      this.inputs[key] = this.employeeToEdit[key]
    })
    this.setProperties()
  },
}
</script>
<style lang="scss" scoped>
.employee-permissions__chips {
  gap: 10px;
  :deep(.accent.v-chip--disabled) {
    opacity: 1;
  }
}
</style>
