import { required, maxLength } from 'vuelidate/lib/validators'

const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.showDialog,
    icon: 'mdi-clipboard-account',
    title: state.inputs._id
      ? 'preferences.admin.editEmployee'
      : 'preferences.admin.addEmployee',
    height: 520,
    maxWidth: 650,
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    onClickCancel: () => {
      methods.track({
        type: 'interaction',
        action: 'click',
        category: 'Preferences',
        screen: 'EmployeeForm',
        name: 'Cancel',
      })
      methods.closeDialogForm()
    },
    onClickAccept: () => methods.saveEmployee(),
  },
  fields: [
    {
      id: 'name',
      type: 'input',
      valueType: 'text',
      label: 'preferences.admin.newEmployee',
      required: true,
      validators: { required, maxLength: maxLength(50) },
      errorMessage: 'preferences.admin.errorEmployeeName',
    },
    {
      id: 'password',
      type: 'password',
      label: 'preferences.admin.introducePassword',
      validators: { required, maxLength: maxLength(25) },
    },
  ],
})

export default setConfig
