<template>
  <div class="pb-6">
    <FormattedText
      type="text-subtitle-1"
      color="textPrimary"
      intl
      value="preferences.app.theme"
      class="text-left"
      className="font-weight-bold"
    />
    <v-switch
      :input-value="darkMode"
      hide-details
      inset
      @change="changeSelectedTheme"
      :label="getTranslatedText('preferences.app.dark')"
    ></v-switch>
  </div>
</template>

<script>
import { mapState, mapActions } from 'vuex'

import { getTranslatedText } from '@/tools/data'

import appActions from '@/store/app/actions.types'

import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'AppThemePreference',
  components: {
    FormattedText,
  },
  computed: {
    ...mapState('app', ['darkMode']),
  },
  methods: {
    getTranslatedText,
    ...mapActions('app', [appActions.setDarkMode]),
    changeSelectedTheme(event) {
      this.$track({
        type: 'interaction',
        action: 'change',
        category: 'Preferences',
        screen: 'App',
        name: `Change ${event ? 'dark' : 'light'} theme`,
      })
      this.$vuetify.theme.dark = event
      this[appActions.setDarkMode](event)
    },
  },
}
</script>
