<template>
  <ScrollContainer :height="`${cardHeight}px`">
    <v-card flat color="cardBackgroundPrimary" v-if="showAll">
      <v-card-text class="pt-2">
        <v-row>
          <v-col v-if="showAirtime" cols="12" md="4">
            <AirtimeServices />
          </v-col>
          <v-col cols="12" md="4">
            <RestoreStockProducts />
          </v-col>
          <v-col cols="12" md="4">
            <ChangePassword />
          </v-col>
        </v-row>
        <v-row>
          <v-col cols="12">
            <Employees />
          </v-col>
        </v-row>
      </v-card-text>
    </v-card>
  </ScrollContainer>
</template>

<script>
import { mapState } from 'vuex'
import { isNil } from 'ramda'

import { testMode } from '@/config/env'
import betaTester, { useFeature } from '@/config/betaTesters'

import Employees from '@/components/PreferencesView/AdminPreferences/Employees'
import AirtimeServices from '@/components/PreferencesView/AdminPreferences/AirtimeServices'
import ChangePassword from '@/components/PreferencesView/AdminPreferences/ChangePassword'
import RestoreStockProducts from '@/components/PreferencesView/AdminPreferences/RestoreStockProducts'
import ScrollContainer from '@/components/shared/ScrollContainer'

export default {
  name: 'AdminPreferences',
  components: {
    ScrollContainer,
    RestoreStockProducts,
    Employees,
    AirtimeServices,
    ChangePassword,
  },
  props: {
    config: {
      type: Object,
      required: true,
    },
  },
  data() {
    return {
      ops: {
        scrollPanel: {
          scrollingX: false,
        },
        rail: {
          gutterOfSide: '-3px',
        },
      },
    }
  },
  computed: {
    ...mapState('account', { accountData: state => state.data }),
    showAll() {
      return this.config.show
    },
    showAirtime() {
      return useFeature(this.accountData, betaTester.airtime)
    },
    cardHeight() {
      if (!isNil(testMode)) return 600
      return (
        document.getElementsByClassName('preferences')[0].offsetHeight * 0.89
      )
    },
  },
}
</script>
