<template>
  <ActionsCard
    title="preferences.pays.editCommissions"
    icon="mdi-point-of-sale"
  >
    <v-list-item
      v-for="paymentCard in paymentProvidersByType.card"
      :key="paymentCard.id"
      class="payment-provider px-2"
    >
      <v-list-item-content class="payment-provider-list py-0">
        <v-list-item-title class="payment-provider-list__name pb-7">
          {{ paymentCard.label }}
        </v-list-item-title>
        <v-text-field
          v-model="inputs[paymentCard.id]"
          type="number"
          class="payment-provider-list__commission"
          filled
          rounded
          dense
          suffix="%"
          background-color="mainBackground"
          :error-messages="onValidate(paymentCard.id)"
          @input="$v.inputs[paymentCard.id].$touch()"
          @change="commissionWasChanged(paymentCard.id)"
          @focus="$event => $event.target.select()"
        />
      </v-list-item-content>
    </v-list-item>
  </ActionsCard>
</template>

<script>
import { mapActions, mapState } from 'vuex'

import PAYMENT_PROVIDERS_DB_API_EVENTS from '@/config/events/databaseAPI/paymentProvidersEvents'

import { getTranslatedText } from '@/tools/data'

import rendererEventsService from '@/services/renderer/rendererEvents'

import salesViewActions from '@/store/salesView/actions.types'

import ActionsCard from '@/components/shared/ActionsCard'

export default {
  name: 'PaymentCommissions',
  components: {
    ActionsCard,
  },
  data() {
    return {
      inputs: {},
      validators: { inputs: {} },
    }
  },
  computed: {
    ...mapState('salesView', ['paymentProvidersByType']),
  },
  validations() {
    return this.validators
  },
  methods: {
    ...mapActions('salesView', [
      salesViewActions.updatePaymentProvidersCommission,
    ]),
    getTranslatedText,
    onValidate(providerId) {
      const errors = []
      if (!this.$v.inputs[providerId].$dirty) return errors
      !this.$v.inputs[providerId].minValue &&
        errors.push(this.getTranslatedText('preferences.pays.errorCommission'))
      !this.$v.inputs[providerId].maxValue &&
        errors.push(this.getTranslatedText('preferences.pays.errorCommission'))
      return errors
    },
    commissionWasChanged(input) {
      this.$v.inputs[input].$touch()
      if (this.$v.inputs[input].$error) return
      this[salesViewActions.updatePaymentProvidersCommission]({
        type: 'card',
        id: input,
        commissions: Number(this.$v.inputs[input].$model),
      })
      rendererEventsService.send(PAYMENT_PROVIDERS_DB_API_EVENTS.channel, {
        event: PAYMENT_PROVIDERS_DB_API_EVENTS.events.update.name,
        data: { id: input, commissions: Number(this.$v.inputs[input].$model) },
      })
    },
    setInputs() {
      this.paymentProvidersByType.card.forEach(provider => {
        this.$set(this.inputs, provider.id, provider.commissions)
        this.$set(this.validators.inputs, provider.id, {
          minValue: value => value >= 0,
          maxValue: value => value < 99,
        })
      })
    },
  },
  beforeMount() {
    this.setInputs()
  },
}
</script>

<style scoped lang="scss">
.payment-provider {
  &-list {
    display: flex;
    justify-content: space-between;
    flex-flow: row nowrap;
    &__name {
      flex-basis: 85%;
    }
    &__commission {
      flex-shrink: 2;
      border-radius: 12px;
      :deep(input) {
        text-align: end;
        &::-webkit-outer-spin-button,
        &::-webkit-inner-spin-button {
          -webkit-appearance: none;
          margin: 0;
        }
        &[type='number'] {
          -moz-appearance: textfield;
        }
      }
    }
  }
}
</style>
