import {
  required,
  integer,
  maxLength,
  maxValue,
} from 'vuelidate/lib/validators'

const setConfig = (state, methods) => ({
  state,
  methods,
  fields: [
    {
      id: 'storeName',
      type: 'input',
      valueType: 'text',
      label: 'shared.storeName',
      errorMessage: 'starterLayout.editProfile.storeNameRequired',
      color: 'primaryColor',
      required: true,
      oneLine: true,
      validators: { required, maxLength: maxLength(95) },
    },
    {
      id: 'state',
      type: 'autocomplete',
      label: `starterLayout.editProfile.state${state.country}`,
      errorMessage: `starterLayout.editProfile.stateRequired${state.country}`,
      items: state.states,
      itemText: 'name',
      color: 'primaryColor',
      required: true,
      validators: { required },
    },
    {
      id: 'town',
      type: 'autocomplete',
      label: `starterLayout.editProfile.town${state.country}`,
      placeholder: `starterLayout.editProfile.townPlaceholder${state.country}`,
      errorMessage: `starterLayout.editProfile.townRequired${state.country}`,
      items: state.towns,
      color: 'primaryColor',
      required: true,
      readonly: state.towns && state.towns.length === 0,
      validators: { required },
    },
    {
      id: 'zipCode',
      type: 'input',
      valueType: 'number',
      step: 1,
      label: 'starterLayout.editProfile.zipCode',
      errorMessage: 'starterLayout.editProfile.zipCodeRequired',
      color: 'primaryColor',
      required: true,
      validators: { required, integer, maxValue: maxValue(999999999) },
    },
    {
      id: 'completeAddress',
      type: 'input',
      valueType: 'text',
      label: 'starterLayout.editProfile.completeAddress',
      errorMessage: 'starterLayout.editProfile.completeAddressRequired',
      color: 'primaryColor',
      required: true,
      validators: { required, maxLength: maxLength(95) },
    },
    {
      id: 'name',
      type: 'input',
      valueType: 'text',
      label: 'shared.ownerName',
      errorMessage: 'starterLayout.editProfile.ownerNameTooLong',
      color: 'primaryColor',
      validators: { maxLength: maxLength(95) },
    },
    {
      id: 'storeLogo',
      type: 'fileInput',
      accept: 'image/png, image/jpeg, image/bmp',
      label: 'starterLayout.editProfile.storeLogo',
      color: 'primaryColor',
      icon: 'mdi-image',
    },
    {
      id: 'storePhone',
      type: 'input',
      valueType: 'number',
      step: 1,
      label: 'shared.phone',
      errorMessage: 'starterLayout.editProfile.mobilePhoneRequired',
      color: 'primaryColor',
      required: true,
      validators: { required, integer, maxValue: maxValue(99999999999) },
    },
    {
      id: 'landlinePhone',
      type: 'input',
      valueType: 'number',
      step: 1,
      label: 'shared.landlinePhone',
      errorMessage: 'starterLayout.editProfile.landlinePhoneTooLong',
      color: 'primaryColor',
      validators: { integer, maxValue: maxValue(99999999999) },
    },
    {
      id: 'email',
      type: 'input',
      valueType: 'text',
      label: 'starterLayout.signUp.email',
      color: 'primaryColor',
      validators: { maxLength: maxLength(95) },
    },
    {
      id: 'storetype',
      type: 'select',
      valueType: 'text',
      label: 'starterLayout.editProfile.storeType',
      items: state.storeTypes,
      itemText: 'name',
      color: 'primaryColor',
    },
    {
      id: 'storeSize',
      type: 'input',
      valueType: 'number',
      step: 1,
      label: 'starterLayout.editProfile.storeSize',
      errorMessage: 'starterLayout.editProfile.integerTooLong',
      color: 'primaryColor',
      suffix: 'm²',
      validators: { integer, maxValue: maxValue(999) },
    },
    {
      id: 'coolersNumber',
      type: 'input',
      valueType: 'number',
      step: 1,
      label: 'starterLayout.editProfile.coolersNumber',
      errorMessage: 'starterLayout.editProfile.integerTooLong',
      color: 'primaryColor',
      validators: { integer, maxValue: maxValue(999) },
    },
  ],
  id: 'edit-profile-first-form',
})

export default setConfig
