<template>
  <div class="">
    <FormattedText
      type="text-subtitle-1"
      color="textPrimary"
      intl
      value="preferences.app.zoom"
      class="text-left"
      className="font-weight-bold"
    />
    <v-container fluid>
      <v-row justify="start">
        <v-col cols="6" class="pl-0">
          <v-slider
            v-model="zoom"
            :tick-labels="ticksLabels"
            :max="4"
            step="1"
            :disabled="autoSelected"
            @change="onUpdateSlider"
            color="accent"
          />
        </v-col>
        <v-spacer />
        <v-col cols="6" class="pt-0">
          <v-checkbox
            v-model="autoSelected"
            :label="getTranslatedText('preferences.app.autoZoom')"
            @change="onUpdateCheckbox"
            color="accent"
          />
        </v-col>
      </v-row>
    </v-container>
  </div>
</template>

<script>
import { mapActions, mapState } from 'vuex'
import { webFrame } from 'electron'
import { isNil } from 'ramda'

import { testMode } from '@/config/env'
import zoomLevels from '@/config/zoomLevels'

import { getTranslatedText } from '@/tools/data'

import appActions from '@/store/app/actions.types'

import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'AppZoomPreference',
  components: { FormattedText },
  data() {
    return {
      autoSelected: false,
      zoom: 2,
      ticksLabels: [],
    }
  },
  computed: {
    ...mapState('app', ['zoomLevel']),
  },
  methods: {
    getTranslatedText,
    ...mapActions('app', [appActions.setZoomLevel]),
    onUpdateSlider() {
      this.$track({
        type: 'interaction',
        action: 'change',
        category: 'Preferences',
        screen: 'App',
        name: 'Change zoom',
      })
      this[appActions.setZoomLevel]({ zoomLevel: this.zoom })
    },
    onUpdateCheckbox() {
      this.$track({
        type: 'interaction',
        action: 'change',
        category: 'Preferences',
        screen: 'App',
        name: 'Change zoom auto',
      })
      this[appActions.setZoomLevel]({ zoomLevel: 'auto' })
      this.initializeSlider()
    },
    initializeSlider() {
      switch (webFrame.getZoomFactor()) {
        case 0.7:
          this.zoom = 0
          return
        case 0.85:
          this.zoom = 1
          return
        case 1:
          this.zoom = 2
          return
        case 1.1:
          this.zoom = 3
          return
        case 1.2:
          this.zoom = 4
          return
        default:
          this.zoom = 2
          return
      }
    },
  },
  mounted() {
    zoomLevels.forEach(level =>
      this.ticksLabels.push(
        this.getTranslatedText(`shared.level.${level.name}`)
      )
    )
    if (this.zoomLevel !== 'auto') {
      this.zoom = this.zoomLevel
      return
    }
    this.autoSelected = true
    if (isNil(testMode)) this.initializeSlider()
  },
}
</script>
