import { required } from 'vuelidate/lib/validators'

const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.isOpen,
    icon: 'mdi-lock-outline',
    title: 'preferences.admin.introduceAdminPwTitle',
    titleBackground: '#white',
    titleColor: 'textPrimary',
    persistent: true,
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    messages: ['preferences.admin.introduceAdminPw'],
    height: 300,
    maxWidth: 500,
    id: 'confirm-admin-password-form',
    onClickCancel: () => {
      methods.track({
        type: 'interaction',
        action: 'click',
        category: 'Preferences',
        screen: 'AdminPasswordDialog',
        name: 'Cancel',
      })
      methods.closeDialog()
    },
    onClickAccept: () => methods.checkPassword(),
  },
  fields: [
    {
      id: 'password',
      type: 'password',
      validators: { required },
      autofocus: true,
    },
  ],
  id: 'confirm-admin-password-form',
})

export default setConfig
