<template>
  <v-card flat class="preferences" color="cardBackgroundPrimary">
    <!-- Preferences header -->
    <v-toolbar flat color="cardBackgroundPrimary">
      <v-icon class="pr-2">mdi-tune</v-icon>
      <v-toolbar-title>
        <FormattedText
          value="preferences.title"
          color="default"
          intl
          type="text-h6"
        />
      </v-toolbar-title>
    </v-toolbar>
    <!-- Preferences content  -->
    <v-card-text>
      <v-tabs
        v-model="currentGroup"
        vertical
        class="tabs"
        background-color="cardBackgroundPrimary"
      >
        <v-tab
          v-for="item in componentConfig.groups"
          :key="item.id"
          :ref="`tab-${item.id}`"
          :href="`#${item.id}`"
          @click="tabWasClicked(item)"
        >
          <!-- TODO: Delete this badge in newer versions -->
          <v-badge
            v-if="item.newFeature"
            color="primary"
            dot
            offset-x="0"
            offset-y="0"
            left
          >
            <v-icon left>{{ item.icon }}</v-icon>
          </v-badge>
          <v-icon v-else left>{{ item.icon }}</v-icon>
          <FormattedText :value="item.title" color="default" intl />
        </v-tab>
        <v-tabs-items v-model="currentGroup">
          <v-tab-item
            v-for="item in componentConfig.groups"
            :key="item.id"
            :ref="`tab-content-${item.id}`"
            :value="item.id"
          >
            <component v-bind:is="item.component" :config="item"></component>
          </v-tab-item>
        </v-tabs-items>
      </v-tabs>
    </v-card-text>
    <AdminPasswordDialog
      v-if="adminPasswordDialog.isOpen"
      @adminPasswordIntroduced="adminPasswordIntroduced = true"
    />
  </v-card>
</template>

<script>
import { mapState, mapActions } from 'vuex'

import PREFERENCES_EVENTS from '@/config/events/databaseAPI/preferencesEvents'

import logger from '@/tools/logger'
import { getObjectCopy } from '@/tools/data'

import i18n from '@/plugins/i18n'

import notificationsService from '@/services/renderer/notifications'
import rendererEventsService from '@/services/renderer/rendererEvents'

import appActions from '@/store/app/actions.types'
import usersViewActions from '@/store/usersView/actions.types'

import Button from '@/components/shared/CustomButton'
import FormattedText from '@/components/shared/FormattedText'
import AppPreferences from '@/components/PreferencesView/AppPreferences'
import AdminPreferences from '@/components/PreferencesView/AdminPreferences'
import PaysPreferences from '@/components/PreferencesView/PaysPreferences'
import PrintPreferences from '@/components/PreferencesView/PrintPreferences'
import SupportPreferences from '@/components/PreferencesView/SupportPreferences'
import InfoPreferences from '@/components/PreferencesView/InfoPreferences'
import ProfilePreferences from '@/components/PreferencesView/ProfilePreferences'
import AdminPasswordDialog from '@/components/PreferencesView/AdminPreferences/AdminPasswordDialog'
import setConfig from '@/components/PreferencesView/config'

export default {
  name: 'PreferencesView',
  components: {
    Button,
    FormattedText,
    AppPreferences,
    AdminPreferences,
    PaysPreferences,
    PrintPreferences,
    SupportPreferences,
    InfoPreferences,
    ProfilePreferences,
    AdminPasswordDialog,
  },
  data() {
    return {
      currentGroup: 'app',
      adminPasswordIntroduced: false,
      nextRoute: null,
      feedbackSaveEvents: { success: [], error: [] },
    }
  },
  computed: {
    ...mapState({ app: state => state.app }),
    ...mapState('app', ['adminPasswordDialog']),
    ...mapState('users', ['users']),
    ...mapState('usersView', ['selectedUser']),
    componentConfig: function() {
      return setConfig(
        { adminPasswordIntroduced: this.adminPasswordIntroduced },
        {}
      )
    },
  },
  methods: {
    ...mapActions('app', [
      appActions.persistPreferences,
      appActions.addPendingSyncOperation,
      appActions.setAdminPasswordDialogStatus,
    ]),
    ...mapActions('usersView', [
      usersViewActions.setSelectedUserFromPreferences,
    ]),
    savePreferences() {
      this.$track({
        type: 'system',
        action: 'go_out',
        category: 'Preferences',
        screen: `${this.currentGroup.charAt(0).toUpperCase() +
          this.currentGroup.slice(1)}`,
        name: 'Save preferences',
      })
      this.$root.$emit('save-profile')
      const preferencesState = getObjectCopy(this.getPreferencesState())
      rendererEventsService.send(PREFERENCES_EVENTS.channel, {
        event: PREFERENCES_EVENTS.events.updateAll.name,
        data: preferencesState,
      })
    },
    setFeedbackSaveEvents(feedbackFromTab, isSuccess) {
      if (isSuccess) {
        this.feedbackSaveEvents.success.push(feedbackFromTab)
      } else {
        this.feedbackSaveEvents.error.push(feedbackFromTab)
      }
      this.showFeedback()
    },
    showFeedback() {
      const totalFeedback = document.getElementById('edit-profile-first-form')
        ? 2
        : 1
      const totalSuccess = this.feedbackSaveEvents.success.length
      const totalErrors = this.feedbackSaveEvents.error.length
      if (totalSuccess + totalErrors < totalFeedback) {
        return
      }
      if (totalSuccess === totalFeedback) {
        this.$track({
          type: 'system',
          action: 'save_preferences',
          category: 'Preferences',
          screen: `${this.currentGroup.charAt(0).toUpperCase() +
            this.currentGroup.slice(1)}`,
          name: `Go to ${this.nextRoute.name}`,
        })
        this[appActions.addPendingSyncOperation]()
        notificationsService.showSuccess(
          'notification.preferences.saved',
          this.$vuetify.lang
        )
        this.$router.push(this.nextRoute)
        return
      }
      this.$track({
        type: 'system',
        action: 'error',
        category: 'Preferences',
        screen: `${this.currentGroup.charAt(0).toUpperCase() +
          this.currentGroup.slice(1)}`,
        name: 'Error saving preferences',
      })
      this.nextRoute = null
      if (this.feedbackSaveEvents.error.find(tab => tab === 'profile')) {
        this.currentGroup = 'profile'
        this.feedbackSaveEvents = { success: [], error: [] }
        return
      }
      this.currentGroup = this.feedbackSaveEvents.error[0]
      this.feedbackSaveEvents = { success: [], error: [] }
      notificationsService.showError(
        'notification.preferences.errorSaving',
        this.$vuetify.lang
      )
    },
    getPreferencesState() {
      const {
        darkMode,
        mainMenuItems,
        zoomLevel,
        forceChangeDialog,
        defaultProductsFilter,
        printTicketDefault,
        showCustomerDataTicket,
        addMarginTicket,
      } = this.app
      return {
        language: i18n.locale,
        darkMode: darkMode.toString(),
        favoriteSections: mainMenuItems.toString(),
        zoomLevel: zoomLevel,
        forceChangeDialog: forceChangeDialog.toString(),
        defaultProductsFilter: defaultProductsFilter,
        printTicketDefault: printTicketDefault.toString(),
        showCustomerDataTicket: showCustomerDataTicket.toString(),
        addMarginTicket: addMarginTicket.toString(),
      }
    },
    preferencesEventsListener(event, payload) {
      if (payload.event === PREFERENCES_EVENTS.events.updateAll.replies.error) {
        this.setFeedbackSaveEvents('app', false)
        return
      }
      this.setFeedbackSaveEvents('app', true)
    },
    introduceAdminPassword() {
      if (
        (this.currentGroup === 'admin' || this.currentGroup === 'profile') &&
        !this.adminPasswordIntroduced
      ) {
        this.$track({
          type: 'system',
          action: 'go_tab',
          category: 'Preferences',
          screen: `${this.currentGroup.charAt(0).toUpperCase() +
            this.currentGroup.slice(1)}`,
          name: 'Add admin password',
        })
        this[appActions.setAdminPasswordDialogStatus](true)
      }
    },
    tabWasClicked(item) {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Preferences',
        screen: `${this.currentGroup.charAt(0).toUpperCase() +
          this.currentGroup.slice(1)}`,
        name: `Go to ${item.id}`,
      })
    },
  },
  watch: {
    currentGroup() {
      logger('info', `User select ${this.currentGroup} preferences group`)
      this.introduceAdminPassword()
    },
  },
  mounted() {
    rendererEventsService.subscribe(
      PREFERENCES_EVENTS.replyChannel,
      this.preferencesEventsListener
    )
    this.$root.$on('profileWasSaved', this.setFeedbackSaveEvents)
    this.$router.beforeEach((to, from, next) => {
      if (this.nextRoute) {
        next()
        return
      }
      this.feedbackSaveEvents = { success: [], error: [] }
      this.nextRoute = to
      this.savePreferences()
    })
    if (this.$route.query && this.$route.query.tab)
      this.currentGroup = this.$route.query.tab
  },
  destroyed() {
    this.$root.$off('profileWasSaved')
    rendererEventsService.removeListener(
      PREFERENCES_EVENTS.replyChannel,
      this.preferencesEventsListener
    )
  },
}
</script>

<style style lang="scss">
.preferences {
  height: 100%;
  .tabs {
    .v-tab {
      justify-content: left;
      width: 220px;
    }
    .v-tabs-items {
      background-color: var(--v-cardBackgroundPrimary-base);
    }
  }
}
</style>
